begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
select has_function('public','superadmin_activity_set_permissions_v2',array['uuid','uuid','bigint','jsonb','jsonb','jsonb'],'permission snapshot exists');
select has_function('public','superadmin_activity_publish_v2',array['uuid','uuid','bigint'],'publish exists');
select ok(not has_function_privilege('authenticated','public.superadmin_activity_set_permissions_v2(uuid,uuid,bigint,jsonb,jsonb,jsonb)','execute'),'Task3 exposes no intermediate authenticated grant');
select ok(not has_function_privilege('service_role','public.superadmin_activity_publish_v2(uuid,uuid,bigint)','execute'),'service role cannot publish');
select is(app_private.activity_v2_effective_permission('prohibited','allow','edit','allow','required','true','default_on','allow'),'none','prohibited wins');
select is(app_private.activity_v2_effective_permission(null,'deny','edit','allow','required','true','default_on','allow'),'none','legacy deny wins');
select is(app_private.activity_v2_effective_permission(null,null,'edit','allow','required','true','default_on','allow'),'edit','explicit action wins');
select is(app_private.activity_v2_effective_permission(null,null,null,'allow','required','true','default_on','allow'),'both','legacy allow wins');
select is(app_private.activity_v2_effective_permission(null,null,null,null,'required','false','default_off','deny'),'both','required wins before setting');
select is(app_private.activity_v2_effective_permission(null,null,null,null,null,'false','default_on','allow'),'none','disabled setting wins over default/profile');
select ok(app_private.activity_v2_effective_permission(null,null,null,null,null,null,'default_on','deny')='both' and app_private.activity_v2_effective_permission(null,null,null,null,null,null,'default_off','allow')='none' and app_private.activity_v2_effective_permission(null,null,null,null,null,null,null,'allow')='both','default_on/default_off precede profile allow/deny');

insert into public.institution_types(id,code,name,status) values('74000000-0000-4000-8000-000000000009','activity-v2-perm','Activity v2 permission','active');
insert into public.institutions(id,public_name,slug,status,institution_type_id) values('74000000-0000-4000-8000-000000000001','Permission Tenant','activity-v2-perm','active','74000000-0000-4000-8000-000000000009');
insert into public.units(id,institution_id,name,slug,status,institution_type_id) values('74000000-0000-4000-8000-000000000011','74000000-0000-4000-8000-000000000001','Permission Unit','activity-v2-perm-unit','active','74000000-0000-4000-8000-000000000009');
insert into public.groups(id,institution_id,unit_id,name,group_type,status) values('74000000-0000-4000-8000-000000000021','74000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000011','Permission Group','class','active');
insert into public.people(id,person_type,first_name,last_name,display_name,status) values('74000000-0000-4000-8000-000000000031','adult','Permission','Professional','Permission Professional','active');
insert into public.institution_memberships(id,person_id,institution_id,role_code,status,scope_kind) values('74000000-0000-4000-8000-000000000041','74000000-0000-4000-8000-000000000031','74000000-0000-4000-8000-000000000001','instructor','active','institution');
insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data) values('74000000-0000-4000-8000-000000000081','authenticated','authenticated','activity-v2-permission@invalid.test',now(),now(),now(),'{}','{}');
insert into auth.sessions(id,user_id,created_at,updated_at,aal,not_after) values('74000000-0000-4000-8000-000000000082','74000000-0000-4000-8000-000000000081',now(),now(),'aal2',now()+interval '1 hour');
insert into app_private.superadmin_internal_identities(id) values('74000000-0000-4000-8000-000000000083');
insert into app_private.superadmin_internal_auth_links(id,internal_identity_id,auth_user_id) values('74000000-0000-4000-8000-000000000084','74000000-0000-4000-8000-000000000083','74000000-0000-4000-8000-000000000081');
insert into app_private.superadmin_internal_memberships(id,internal_identity_id,platform_role_id,scope_kind) select '74000000-0000-4000-8000-000000000085','74000000-0000-4000-8000-000000000083',id,'platform' from public.platform_roles where code='owner';
select set_config('request.jwt.claims',jsonb_build_object('sub','74000000-0000-4000-8000-000000000081','session_id','74000000-0000-4000-8000-000000000082','aal','aal2','role','authenticated')::text,true);
create temporary table activity_v2_perm_result(kind text primary key,body jsonb);
insert into activity_v2_perm_result values('create',public.superadmin_activity_create_v2('74000000-0000-4000-8000-000000000091',jsonb_build_object('institution_id','74000000-0000-4000-8000-000000000001','name','Permission Activity','description','Synthetic','taxonomy_id',(select id from public.activity_taxonomies where code='musica'),'icon_key','music_note','initials','PA','unit_ids',jsonb_build_array('74000000-0000-4000-8000-000000000011'))));
insert into activity_v2_perm_result values('groups',public.superadmin_activity_set_groups_v2('74000000-0000-4000-8000-000000000092',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),1,array['74000000-0000-4000-8000-000000000021'::uuid],jsonb_build_object('74000000-0000-4000-8000-000000000021','selected')));
insert into activity_v2_perm_result values('professionals',public.superadmin_activity_set_professionals_v2('74000000-0000-4000-8000-000000000093',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),2,jsonb_build_array(jsonb_build_object('membership_id','74000000-0000-4000-8000-000000000041','role','instructor','group_id','74000000-0000-4000-8000-000000000021'))));
select ok((select bool_and((body->>'ok')::boolean) from activity_v2_perm_result),'real internal setup commands all succeed');

with codes as(select value#>>'{}' code from jsonb_array_elements('["chat","now","happens","moments","attendance"]'))
insert into activity_v2_perm_result select 'permissions',public.superadmin_activity_set_permissions_v2('74000000-0000-4000-8000-000000000094',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),3,
 (select jsonb_object_agg(code,'required') from codes),
 jsonb_build_array(jsonb_build_object('group_id','74000000-0000-4000-8000-000000000021','capabilities',(select jsonb_object_agg(code,true) from codes))),
 jsonb_build_array(jsonb_build_object('membership_id','74000000-0000-4000-8000-000000000041','role','instructor','group_id','74000000-0000-4000-8000-000000000021','actions',(select jsonb_object_agg(code,'edit') from codes))));
select ok((select (body->>'ok')::boolean and (body#>>'{data,management_version}')::bigint=4 from activity_v2_perm_result where kind='permissions'),'full five-capability snapshot succeeds once');
insert into activity_v2_perm_result values('detail',public.superadmin_activity_detail_v2((select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),array['permissions']));
select ok((select count(*) from public.activity_capability_policies where activity_id=(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'))=5 and (select count(*) from public.activity_assignment_capability_actions x join public.activity_group_assignments a on a.id=x.assignment_id join public.activity_group_links g on g.id=a.activity_group_link_id where g.activity_id=(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'))=5 and (select jsonb_array_length(body#>'{data,permissions,professional_actions}')=1 and (select array_agg(key order by key) from jsonb_object_keys(body#>'{data,permissions,professional_actions,0}') key)=array['actions','group_id','membership_id','role']::text[] and (select array_agg(key order by key) from jsonb_object_keys(body#>'{data,permissions,professional_actions,0,actions}') key)=array['attendance','chat','happens','moments','now']::text[] and body#>>'{data,permissions,professional_actions,0,actions,chat}'='edit' from activity_v2_perm_result where kind='detail'),'all five policies and explicit professional actions persist and reload through the allowlisted detail contract');

insert into activity_v2_perm_result values('invalid_shape',public.superadmin_activity_set_permissions_v2('74000000-0000-4000-8000-000000000099',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),4,'{"chat":"required","now":null,"happens":null,"moments":null,"attendance":null}',jsonb_build_array(jsonb_build_object('group_id','74000000-0000-4000-8000-000000000021','capabilities','{"chat":true}'::jsonb)),'[]'));
insert into activity_v2_perm_result values('required_none',public.superadmin_activity_set_permissions_v2('74000000-0000-4000-8000-000000000095',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),4,'{"chat":"required","now":null,"happens":null,"moments":null,"attendance":null}',jsonb_build_array(jsonb_build_object('group_id','74000000-0000-4000-8000-000000000021','capabilities','{"chat":true,"now":null,"happens":null,"moments":null,"attendance":null}'::jsonb)),jsonb_build_array(jsonb_build_object('membership_id','74000000-0000-4000-8000-000000000041','role','instructor','group_id','74000000-0000-4000-8000-000000000021','actions','{"chat":"none","now":"none","happens":"none","moments":"none","attendance":"none"}'::jsonb))));
select ok((select body#>>'{error,code}'='ACTIVITY_INVALID_INPUT' from activity_v2_perm_result where kind='required_none') and (select body#>>'{error,code}'='ACTIVITY_INVALID_INPUT' from activity_v2_perm_result where kind='invalid_shape'),'required rejects explicit none and every nested snapshot requires the exact five-key schema');
select is((select management_version from public.activity_definitions where id=(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create')),4::bigint,'rejected permission snapshot does not bump version');
insert into activity_v2_perm_result values('clear',public.superadmin_activity_set_permissions_v2('74000000-0000-4000-8000-000000000096',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),4,'{"chat":null,"now":null,"happens":null,"moments":null,"attendance":null}','[]','[]'));
select ok((select (body->>'ok')::boolean from activity_v2_perm_result where kind='clear') and not exists(select 1 from public.activity_capability_policies where activity_id=(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create')) and not exists(select 1 from public.activity_group_capability_settings s join public.activity_group_links g on g.id=s.activity_group_link_id where g.activity_id=(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create')) and not exists(select 1 from public.activity_assignment_capability_actions x join public.activity_group_assignments a on a.id=x.assignment_id join public.activity_group_links g on g.id=a.activity_group_link_id where g.activity_id=(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create')),'omitted snapshots clear every stale policy, setting and action');
with codes as(select value#>>'{}' code from jsonb_array_elements('["chat","now","happens","moments","attendance"]')) insert into activity_v2_perm_result select 'restore',public.superadmin_activity_set_permissions_v2('74000000-0000-4000-8000-000000000097',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),5,(select jsonb_object_agg(code,'required') from codes),jsonb_build_array(jsonb_build_object('group_id','74000000-0000-4000-8000-000000000021','capabilities',(select jsonb_object_agg(code,true) from codes))),jsonb_build_array(jsonb_build_object('membership_id','74000000-0000-4000-8000-000000000041','role','instructor','group_id','74000000-0000-4000-8000-000000000021','actions',(select jsonb_object_agg(code,'both') from codes))));
insert into activity_v2_perm_result values('publish',public.superadmin_activity_publish_v2('74000000-0000-4000-8000-000000000098',(select (body#>>'{data,activity_id}')::uuid from activity_v2_perm_result where kind='create'),6));
select ok((select (body->>'ok')::boolean and body#>>'{data,status}'='active' and (body#>>'{data,management_version}')::bigint=7 from activity_v2_perm_result where kind='publish'),'draft with complete structure and five explicit actions publishes once');
select * from finish();
rollback;
